/* Read-only preflight: no volume, route, DND or lock settings are changed. */
import android.app.KeyguardManager;
import android.app.NotificationManager;
import android.media.AudioManager;
import android.media.AudioDeviceInfo;
import android.os.PowerManager;
import android.os.Build;
import com.joaomgcd.taskerm.action.java.JavaCodeException;
try {
pm = context.getSystemService("power");
km = context.getSystemService("keyguard");
if (!pm.isInteractive() || km.isKeyguardLocked())
    throw new JavaCodeException("Turn on and unlock the phone before controlling Signia");
am = context.getSystemService("audio");
nm = context.getSystemService("notification");
streamName = tasker.getVariable("SIG3_AudioStream");
if (!"media".equals(streamName) && !"ring".equals(streamName))
    throw new JavaCodeException("Set SIG3_AudioStream to Signia's selected media or ring stream");
stream = "ring".equals(streamName) ? AudioManager.STREAM_RING : AudioManager.STREAM_MUSIC;
volume = am.getStreamVolume(stream);
maximum = am.getStreamMaxVolume(stream);
mode = am.getMode();
ringer = am.getRingerMode();
minimumText = tasker.getVariable("SIG3_MinAudioPercent");
minimumPercent = 50;
if (minimumText != null && !minimumText.equals("") && !minimumText.startsWith("%")) {
    if (!minimumText.matches("[0-9]{1,3}"))
        throw new JavaCodeException("Set SIG3_MinAudioPercent to an integer from 1 to 100");
    minimumPercent = Integer.parseInt(minimumText);
}
if (minimumPercent < 1 || minimumPercent > 100)
    throw new JavaCodeException("Set SIG3_MinAudioPercent to an integer from 1 to 100");
required = (maximum * minimumPercent + 99) / 100;
filter = nm.getCurrentInterruptionFilter();
outputs = am.getDevices(AudioManager.GET_DEVICES_OUTPUTS);
route = "";
external = false;
for (device : outputs) {
    type = device.getType();
    route = route + type + ":" + device.getProductName() + ";";
    /* Known connected external outputs; presence is conservative, not an active-route claim. */
    if (type == 3 || type == 4 || type == 7 || type == 8 || type == 11 || type == 12 || type == 22 || type == 23 || type == 26 || type == 27)
        external = true;
}
tasker.setVariable("SIG3_AudioDiagnostics", "stream=" + streamName + " volume=" + volume + "/" + maximum + "; minimum=" + required + "/" + maximum + "; ringerMode=" + ringer + "; mode=" + mode + "; interruptionFilter=" + filter + "; outputs=" + route);
/* BEGIN AUDIO POLICY: also exercised without Android by the policy test. */
if (filter != NotificationManager.INTERRUPTION_FILTER_ALL)
    throw new JavaCodeException("Turn off Do Not Disturb (including bedtime/night mode), then retry the Signia command");
if (ringer == AudioManager.RINGER_MODE_SILENT || ("ring".equals(streamName) && ringer != AudioManager.RINGER_MODE_NORMAL))
    throw new JavaCodeException("Unmute the phone; for Ring sound, also turn off vibrate-only mode, then retry");
if (maximum <= 0 || volume < required)
    throw new JavaCodeException("Raise phone " + streamName + " volume with the phone volume slider to at least " + required + "/" + maximum + " (" + minimumPercent + "% minimum), then retry");
/* END AUDIO POLICY */
if (mode == AudioManager.MODE_IN_CALL || mode == AudioManager.MODE_IN_COMMUNICATION)
    throw new JavaCodeException("Phone call or communication audio is active");
if (external) throw new JavaCodeException("Disconnect external audio outputs before acoustic control");
return "ready";

} catch (Exception failure) {
    tasker.setVariable("SIG3_Error", failure.toString());
    throw failure;
}

/* Program selection through visible accessibility nodes, never fixed coordinates. */
import android.view.accessibility.AccessibilityNodeInfo;
import android.accessibilityservice.AccessibilityServiceInfo;
import com.joaomgcd.taskerm.action.java.JavaCodeException;
import android.os.SystemClock;
import android.accessibilityservice.AccessibilityService;
import android.accessibilityservice.GestureDescription;
import android.graphics.Path;
import android.os.Build;
import android.os.Handler;
import android.os.Looper;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.Callable;
import java.util.concurrent.atomic.AtomicReference;
import com.joaomgcd.taskerm.action.java.ClassImplementation;
import com.joaomgcd.taskerm.action.java.JavaCodeException;


performStroke(service, stroke, phase) {
    signal = new CountDownLatch(1);
    result = new AtomicReference("timeout");
    callback = tasker.implementClass(AccessibilityService.GestureResultCallback.class,
        new ClassImplementation() {
            run(Callable superCaller, String methodName, Object[] args) {
                if (methodName.equals("onCompleted")) {
                    result.set("completed");
                    signal.countDown();
                    return null;
                }
                if (methodName.equals("onCancelled")) {
                    result.set("cancelled");
                    signal.countDown();
                    return null;
                }
                return superCaller.call();
            }
        });
    tasker.setVariable("SIG3_TouchStage", phase);
    gesture = new GestureDescription.Builder().addStroke(stroke).build();
    if (!service.dispatchGesture(gesture, callback, new Handler(Looper.getMainLooper())))
        throw new JavaCodeException(phase + ": dispatchGesture rejected");
    if (!signal.await(3, TimeUnit.SECONDS))
        throw new JavaCodeException(phase + ": completion timed out after 3000 ms");
    if (!result.get().equals("completed"))
        throw new JavaCodeException(phase + ": Android cancelled gesture");
}

visibleNodes(root, id) {
    result = new java.util.ArrayList();
    queue = new java.util.ArrayList(); queue.add(root);
    for (scan = 0; scan < queue.size() && scan < 300; scan++) {
        node = (AccessibilityNodeInfo) queue.get(scan);
        if (node.isVisibleToUser() && node.isEnabled() && id != null && id.equals(node.getViewIdResourceName())) result.add(node);
        for (childIndex = 0; childIndex < node.getChildCount() && queue.size() < 300; childIndex++) {
            child = node.getChild(childIndex); if (child != null) queue.add(child);
        }
    }
    return result;
}
clickNode(service, node, backend) {
    if ("gesture-tap".equals(backend)) {
        if (Build.VERSION.SDK_INT < 24) throw new JavaCodeException("Program tap requires Android 7 or later");
        rect = new android.graphics.Rect(); node.getBoundsInScreen(rect);
        metrics = service.getResources().getDisplayMetrics();
        x = rect.centerX(); y = rect.centerY();
        if (rect.isEmpty() || x < 0 || y < 0 || x >= metrics.widthPixels || y >= metrics.heightPixels)
            throw new JavaCodeException("Program button bounds are outside the display");
        tasker.setVariable("SIG3_Gesture", "Program button tap at " + x + "," + y + "; bounds=" + rect);
        path = new Path(); path.moveTo(x, y);
        performStroke(service, new GestureDescription.StrokeDescription(path, 0, 100, false), "program-tap");
        return;
    }
    if (!"accessibility-click".equals(backend)) throw new JavaCodeException("Set SIG3_ProgramBackend to accessibility-click or gesture-tap");
    for (int depth = 0; depth < 5 && node != null; depth++) {
        if (node.isClickable()) {
            if (!node.performAction(AccessibilityNodeInfo.ACTION_CLICK)) throw new JavaCodeException("Accessibility click rejected");
            return;
        }
        node = node.getParent();
    }
    throw new JavaCodeException("No clickable ancestor for selected node");
}
readProgram(service, id) {
    if (id == null || id.trim().length() == 0 || id.startsWith("%")) throw new JavaCodeException("Configure SIG3_ProgramId");
    root = service.getRootInActiveWindow();
    if (root == null || root.getPackageName() == null || !"com.signia.rta".contentEquals(root.getPackageName())) throw new JavaCodeException("Signia is not foreground");
    queue = new java.util.ArrayList(); queue.add(root);
    count = 0; program = null; headerCount = 0; headerProgram = null;
    for (scan = 0; scan < queue.size() && scan < 300; scan++) {
        node = (AccessibilityNodeInfo) queue.get(scan);
        if (node.isVisibleToUser() && node.isEnabled()) {
            description = node.getContentDescription();
            if (description != null) {
                header = description.toString();
                if (header.startsWith("Hearing program ") && header.endsWith(" Active")) {
                    name = header.substring("Hearing program ".length(), header.length() - " Active".length()).trim();
                    if (name.length() > 0) { headerProgram = name; headerCount++; }
                }
            }
            if (id.equals(node.getViewIdResourceName())) {
                value = node.getText();
                if (value != null && value.toString().trim().length() > 0) {
                    program = value.toString().trim(); count++;
                }
            }
        }
        for (childIndex = 0; childIndex < node.getChildCount() && queue.size() < 300; childIndex++) {
            child = node.getChild(childIndex);
            if (child != null) queue.add(child);
        }
    }
    if (count == 0 && headerCount == 1) { program = headerProgram; count = 1; }
    if (count != 1 || headerCount > 1) throw new JavaCodeException("Cannot identify current program unambiguously");
    if (headerCount == 1 && !headerProgram.equals(program)) throw new JavaCodeException("Program label and active header disagree");
    return program;
}
try {
service = tasker.getAccessibilityService();
if (service == null) throw new JavaCodeException("Enable Tasker accessibility");
info = service.getServiceInfo();
if (info == null) throw new JavaCodeException("Tasker accessibility information unavailable");
info.flags = info.flags | AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS;
service.setServiceInfo(info);
backend = tasker.getVariable("SIG3_ProgramBackend");
if (backend == null || backend.length() == 0 || backend.startsWith("%")) backend = "accessibility-click";
requested = tasker.getVariable("par1");
if (requested == null || !requested.matches("[1-6]")) throw new JavaCodeException("Program slot must be 1–6");
target = tasker.getVariable("SIG3_ProgramName" + requested);
if (target == null || target.trim().length() == 0 || target.startsWith("%")) throw new JavaCodeException("Configure SIG3_ProgramName" + requested + " from the actual program list");
target = target.trim();
id = tasker.getVariable("SIG3_ProgramId");
previous = readProgram(service, id);
tasker.setVariable("SIG3_Previous", previous);
tasker.setVariable("SIG3_Expected", target);
if (!previous.equals(target)) {
    root = service.getRootInActiveWindow();
    open = visibleNodes(root, tasker.getVariable("SIG3_ProgramOpenId"));
    if (open.size() != 1) throw new JavaCodeException("Program opener missing/ambiguous; configure SIG3_ProgramOpenId");
    clickNode(service, open.get(0), backend);
    selected = false;
    for (int attempt = 0; attempt < 20 && !selected; attempt++) {
        SystemClock.sleep(150);
        root = service.getRootInActiveWindow();
        if (root == null || root.getPackageName() == null || !"com.signia.rta".contentEquals(root.getPackageName())) throw new JavaCodeException("Program chooser not in Signia");
        candidates = new java.util.ArrayList();
        queue = new java.util.ArrayList(); queue.add(root);
        for (scan = 0; scan < queue.size() && scan < 300; scan++) {
            item = (AccessibilityNodeInfo) queue.get(scan); candidates.add(item);
            for (childIndex = 0; childIndex < item.getChildCount() && queue.size() < 300; childIndex++) {
                child = item.getChild(childIndex); if (child != null) queue.add(child);
            }
        }
        exact = new java.util.ArrayList();
        for (node : candidates) if (node.isVisibleToUser() && node.isEnabled() && node.getText() != null && target.equals(node.getText().toString().trim())) exact.add(node);
        if (exact.size() > 1) throw new JavaCodeException("Program name matches multiple visible items");
        if (exact.size() == 1) { clickNode(service, exact.get(0), backend); selected = true; }
    }
    if (!selected) throw new JavaCodeException("Configured program not found");
}
for (int attempt = 0; attempt < 20; attempt++) {
    SystemClock.sleep(150);
    try {
        observed = readProgram(service, id);
        tasker.setVariable("SIG3_Observed", observed);
        if (target.equals(observed)) {
            tasker.setVariable("SIG3_Program", observed);
            return "displayed";
        }
    } catch (JavaCodeException unavailable) { }
}
throw new JavaCodeException("Program did not become the configured target; inspect Signia before retrying");

} catch (Exception failure) {
    tasker.setVariable("SIG3_Error", failure.toString());
    throw failure;
}

/* Read-only current program query; no picker click or acoustic command. */
import android.accessibilityservice.AccessibilityServiceInfo;
import android.view.accessibility.AccessibilityNodeInfo;
import com.joaomgcd.taskerm.action.java.JavaCodeException;
try {
service = tasker.getAccessibilityService();
if (service == null) throw new JavaCodeException("Enable Tasker accessibility");
info = service.getServiceInfo();
if (info == null) throw new JavaCodeException("Tasker accessibility information unavailable");
info.flags = info.flags | AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS;
service.setServiceInfo(info);
root = service.getRootInActiveWindow();
if (root == null || root.getPackageName() == null || !"com.signia.rta".contentEquals(root.getPackageName()))
    throw new JavaCodeException("Signia is not foreground");
id = tasker.getVariable("SIG3_ProgramId");
if (id == null || id.trim().length() == 0) throw new JavaCodeException("Configure SIG3_ProgramId");
queue = new java.util.ArrayList(); queue.add(root);
count = 0; program = null; headerCount = 0; headerProgram = null;
for (scan = 0; scan < queue.size() && scan < 300; scan++) {
    node = (AccessibilityNodeInfo) queue.get(scan);
    if (node.isVisibleToUser() && node.isEnabled()) {
        description = node.getContentDescription();
        if (description != null) {
            header = description.toString();
            if (header.startsWith("Hearing program ") && header.endsWith(" Active")) {
                name = header.substring("Hearing program ".length(), header.length() - " Active".length()).trim();
                if (name.length() > 0) { headerProgram = name; headerCount++; }
            }
        }
        if (id.equals(node.getViewIdResourceName())) {
            value = node.getText();
            if (value != null && value.toString().trim().length() > 0) {
                program = value.toString().trim(); count++;
            }
        }
    }
    for (childIndex = 0; childIndex < node.getChildCount() && queue.size() < 300; childIndex++) {
        child = node.getChild(childIndex);
        if (child != null) queue.add(child);
    }
}
if (count == 0 && headerCount == 1) { program = headerProgram; count = 1; }
if (count != 1 || headerCount > 1) throw new JavaCodeException("Cannot identify current program unambiguously");
if (headerCount == 1 && !headerProgram.equals(program)) throw new JavaCodeException("Program label and active header disagree");
tasker.setVariable("SIG3_Program", program);
tasker.setVariable("SIG3_Observed", program);
return "displayed";
} catch (Exception failure) {
    tasker.setVariable("SIG3_Error", failure.toString());
    throw failure;
}

/* Read-only preflight: no volume, route, DND or lock settings are changed. */
import android.app.KeyguardManager;
import android.app.NotificationManager;
import android.media.AudioManager;
import android.media.AudioDeviceInfo;
import android.os.PowerManager;
import android.os.Build;
import com.joaomgcd.taskerm.action.java.JavaCodeException;
try {
pm = context.getSystemService("power");
km = context.getSystemService("keyguard");
if (!pm.isInteractive() || km.isKeyguardLocked())
    throw new JavaCodeException("Turn on and unlock the phone before controlling Signia");
am = context.getSystemService("audio");
nm = context.getSystemService("notification");
streamName = tasker.getVariable("SIG3_AudioStream");
if (!"media".equals(streamName) && !"ring".equals(streamName))
    throw new JavaCodeException("Set SIG3_AudioStream to Signia's selected media or ring stream");
stream = "ring".equals(streamName) ? AudioManager.STREAM_RING : AudioManager.STREAM_MUSIC;
volume = am.getStreamVolume(stream);
maximum = am.getStreamMaxVolume(stream);
mode = am.getMode();
ringer = am.getRingerMode();
minimumText = tasker.getVariable("SIG3_MinAudioPercent");
minimumPercent = 50;
if (minimumText != null && !minimumText.equals("") && !minimumText.startsWith("%")) {
    if (!minimumText.matches("[0-9]{1,3}"))
        throw new JavaCodeException("Set SIG3_MinAudioPercent to an integer from 1 to 100");
    minimumPercent = Integer.parseInt(minimumText);
}
if (minimumPercent < 1 || minimumPercent > 100)
    throw new JavaCodeException("Set SIG3_MinAudioPercent to an integer from 1 to 100");
required = (maximum * minimumPercent + 99) / 100;
filter = nm.getCurrentInterruptionFilter();
outputs = am.getDevices(AudioManager.GET_DEVICES_OUTPUTS);
route = "";
external = false;
for (device : outputs) {
    type = device.getType();
    route = route + type + ":" + device.getProductName() + ";";
    /* Known connected external outputs; presence is conservative, not an active-route claim. */
    if (type == 3 || type == 4 || type == 7 || type == 8 || type == 11 || type == 12 || type == 22 || type == 23 || type == 26 || type == 27)
        external = true;
}
tasker.setVariable("SIG3_AudioDiagnostics", "stream=" + streamName + " volume=" + volume + "/" + maximum + "; minimum=" + required + "/" + maximum + "; ringerMode=" + ringer + "; mode=" + mode + "; interruptionFilter=" + filter + "; outputs=" + route);
/* BEGIN AUDIO POLICY: also exercised without Android by the policy test. */
if (filter != NotificationManager.INTERRUPTION_FILTER_ALL)
    throw new JavaCodeException("Turn off Do Not Disturb (including bedtime/night mode), then retry the Signia command");
if (ringer == AudioManager.RINGER_MODE_SILENT || ("ring".equals(streamName) && ringer != AudioManager.RINGER_MODE_NORMAL))
    throw new JavaCodeException("Unmute the phone; for Ring sound, also turn off vibrate-only mode, then retry");
if (maximum <= 0 || volume < required)
    throw new JavaCodeException("Raise phone " + streamName + " volume with the phone volume slider to at least " + required + "/" + maximum + " (" + minimumPercent + "% minimum), then retry");
/* END AUDIO POLICY */
if (mode == AudioManager.MODE_IN_CALL || mode == AudioManager.MODE_IN_COMMUNICATION)
    throw new JavaCodeException("Phone call or communication audio is active");
if (external) throw new JavaCodeException("Disconnect external audio outputs before acoustic control");
return "ready";

} catch (Exception failure) {
    tasker.setVariable("SIG3_Error", failure.toString());
    throw failure;
}

/* Opens battery UI and records visible information; never invents acoustic percentages. */
import android.view.accessibility.AccessibilityNodeInfo;
import android.accessibilityservice.AccessibilityServiceInfo;
import android.os.SystemClock;
import com.joaomgcd.taskerm.action.java.JavaCodeException;
visibleTree(service) {
    root = service.getRootInActiveWindow();
    if (root == null || root.getPackageName() == null || !"com.signia.rta".contentEquals(root.getPackageName()))
        throw new JavaCodeException("Signia is not foreground");
    queue = new java.util.ArrayList(); queue.add(root);
    visible = new java.util.ArrayList();
    for (scan = 0; scan < queue.size() && scan < 300; scan++) {
        node = (AccessibilityNodeInfo) queue.get(scan);
        if (node.isVisibleToUser() && node.isEnabled()) visible.add(node);
        for (childIndex = 0; childIndex < node.getChildCount() && queue.size() < 300; childIndex++) {
            child = node.getChild(childIndex); if (child != null) queue.add(child);
        }
    }
    return visible;
}
matching(nodes, id, description) {
    found = new java.util.ArrayList();
    for (node : nodes) {
        if (id != null && id.equals(node.getViewIdResourceName())) found.add(node);
    }
    if (found.size() == 0 && description != null && description.length() > 0 && !description.startsWith("%")) {
        for (node : nodes) if (node.getContentDescription() != null && description.contentEquals(node.getContentDescription())) found.add(node);
    }
    return found;
}
try {
service = tasker.getAccessibilityService();
if (service == null) throw new JavaCodeException("Enable Tasker accessibility");
info = service.getServiceInfo();
if (info == null) throw new JavaCodeException("Tasker accessibility information unavailable");
info.flags = info.flags | AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS; service.setServiceInfo(info);
mode = tasker.getVariable("par1");
if (!"open".equals(mode) && !"listen".equals(mode)) throw new JavaCodeException("Battery mode must be open or listen");
pageId = tasker.getVariable("SIG3_BatteryPageId");
if (pageId == null || pageId.length() == 0 || pageId.startsWith("%")) throw new JavaCodeException("Configure SIG3_BatteryPageId");
nodes = visibleTree(service);
page = matching(nodes, pageId, null);
if (page.size() > 1) throw new JavaCodeException("Battery page marker is ambiguous");
if (page.size() == 0) {
    open = matching(nodes, tasker.getVariable("SIG3_BatteryOpenId"), tasker.getVariable("SIG3_BatteryOpenDescription"));
    if (open.size() != 1) throw new JavaCodeException("Battery opener missing/ambiguous; configure its captured ID or description");
    found = (AccessibilityNodeInfo) open.get(0); clicked = false;
    for (depth = 0; found != null && depth < 5; depth++) {
        if (found.isClickable()) {
            if (!found.performAction(AccessibilityNodeInfo.ACTION_CLICK)) throw new JavaCodeException("Battery click rejected");
            clicked = true; break;
        }
        found = found.getParent();
    }
    if (!clicked) throw new JavaCodeException("Battery opener has no clickable ancestor");
    for (attempt = 0; attempt < 20; attempt++) {
        SystemClock.sleep(150);
        nodes = visibleTree(service); page = matching(nodes, pageId, null);
        if (page.size() > 1) throw new JavaCodeException("Battery page marker is ambiguous");
        if (page.size() == 1) break;
    }
    if (page.size() != 1) throw new JavaCodeException("Battery page marker missing; configure SIG3_BatteryPageId");
}
text = "";
for (node : nodes) if (node.getText() != null) text = text + node.getText() + "\n";
tasker.setVariable("SIG3_BatteryText", text);
tasker.setVariable("SIG3_Observed", "Battery page opened; visible text recorded. No aid battery percentage inferred.");
return "opened";
} catch (Exception failure) {
    tasker.setVariable("SIG3_Error", failure.toString()); throw failure;
}

/* Sample indices are not calibrated sound-pressure dB. Never infer sensor units. */
import com.joaomgcd.taskerm.action.java.JavaCodeException;
readSetting(key, fallback) { value = tasker.getVariable(key); return value == null ? fallback : value; }
raw = tasker.getVariable("sig3_noise_raw");
if (raw == null || !raw.matches("-?[0-9]+(?:\\.[0-9]+)?")) throw new JavaCodeException("Noise source did not return a numeric sample");
sample = Double.parseDouble(raw);
if (Double.isNaN(sample) || Double.isInfinite(sample)) throw new JavaCodeException("Invalid noise sample");
if ("1".equals(readSetting("SIG3_NoiseInvert", "0"))) sample = -sample;
tasker.setVariable("SIG3_NoiseRaw", raw);
tasker.setVariable("SIG3_NoiseIndex", sample);
tasker.setVariable("SIG3_Observed", "Uncalibrated noise index " + sample);
tasker.setVariable("SIG3_AutoProgramSlot", "");
if (!"1".equals(readSetting("SIG3_NoiseEnabled", "0"))) return "sample-only";
if (!"1".equals(readSetting("SIG3_NoiseScaleConfirmed", "0"))) throw new JavaCodeException("Confirm noise index sign and units before enabling automation");
if ("1".equals(readSetting("SIG3_ManualOverride", "0"))) { tasker.setVariable("SIG3_NoiseCandidate", ""); tasker.setVariable("SIG3_NoiseStrikes", "0"); return "manual-override"; }
if ("1".equals(readSetting("SIG3_SleepActive", "0"))) return "sleep-active";
lowText = tasker.getVariable("SIG3_NoiseLow"); highText = tasker.getVariable("SIG3_NoiseHigh");
if (lowText == null || highText == null) throw new JavaCodeException("Configure thresholds in the measured noise index units");
low = Double.parseDouble(lowText); high = Double.parseDouble(highText);
limit = Integer.parseInt(readSetting("SIG3_NoiseStrikeLimit", "3"));
if (Double.isNaN(low) || Double.isNaN(high) || Double.isInfinite(low) || Double.isInfinite(high) || low >= high || limit < 1 || limit > 20) throw new JavaCodeException("Invalid noise thresholds or strike limit");
tier = sample >= high ? "loud" : sample <= low ? "quiet" : "middle";
middleSlot = tasker.getVariable("SIG3_NoiseMiddleProgram");
if ("middle".equals(tier) && (middleSlot == null || middleSlot.length() == 0)) { tasker.setVariable("SIG3_NoiseCandidate", ""); tasker.setVariable("SIG3_NoiseStrikes", "0"); return "dead-band"; }
candidate = readSetting("SIG3_NoiseCandidate", "");
strikes = tier.equals(candidate) ? Integer.parseInt(readSetting("SIG3_NoiseStrikes", "0")) + 1 : 1;
if (strikes > limit) strikes = limit;
tasker.setVariable("SIG3_NoiseCandidate", tier);
tasker.setVariable("SIG3_NoiseStrikes", strikes);
if (strikes < limit) return "collecting";
slot = "middle".equals(tier) ? middleSlot : tasker.getVariable("loud".equals(tier) ? "SIG3_NoiseLoudProgram" : "SIG3_NoiseQuietProgram");
if (slot == null || !slot.matches("[1-6]")) throw new JavaCodeException("Configure the noise program slot (1–6)");
tasker.setVariable("SIG3_AutoProgramSlot", slot);
return "target-ready";

/* Automatic changes must not take over another app by default. */
import com.joaomgcd.taskerm.action.java.JavaCodeException;
if ("1".equals(tasker.getVariable("SIG3_AutomationCancelled"))) throw new JavaCodeException("Automatic change cancelled");
if ("1".equals(tasker.getVariable("SIG3_ManualOverride"))) throw new JavaCodeException("Manual override blocks automatic changes");
if (!"0".equals(tasker.getVariable("SIG3_DeferAutomation"))) {
    service = tasker.getAccessibilityService();
    root = service == null ? null : service.getRootInActiveWindow();
    if (root == null || root.getPackageName() == null || !"com.signia.rta".contentEquals(root.getPackageName()))
        throw new JavaCodeException("Automatic change deferred until Signia is foreground");
}
return "allowed";

/* Automatic changes must not take over another app by default. */
import com.joaomgcd.taskerm.action.java.JavaCodeException;
if ("1".equals(tasker.getVariable("SIG3_AutomationCancelled"))) throw new JavaCodeException("Automatic change cancelled");
if ("1".equals(tasker.getVariable("SIG3_ManualOverride"))) throw new JavaCodeException("Manual override blocks automatic changes");
if (!"0".equals(tasker.getVariable("SIG3_DeferAutomation"))) {
    service = tasker.getAccessibilityService();
    root = service == null ? null : service.getRootInActiveWindow();
    if (root == null || root.getPackageName() == null || !"com.signia.rta".contentEquals(root.getPackageName()))
        throw new JavaCodeException("Automatic change deferred until Signia is foreground");
}
return "allowed";

/* Normalize numeric commands and configured semantic program aliases. */
import com.joaomgcd.taskerm.action.java.JavaCodeException;
input = tasker.getVariable("sig3_command");
if (input == null || input.trim().length() == 0) throw new JavaCodeException("No command text supplied");
input = input.trim().replaceAll("(?i)^sig(?:3)?\\s+", "");
// A short spoken name for tinnitus; do not rewrite program names.
input = input.replaceAll("(?i)^((?:(?:set|change|current|maximum|mute)\\s+|what is\\s+(?:the\\s+)?(?:current\\s+)?)?)tin(?=\\s|$)", "$1tinnitus");
alias = input.toLowerCase().replaceAll("^(?:mode|program)\\s+", "");
key = null;
if (alias.equals("conversation") || alias.equals("normal")) key = "SIG3_ModeConversationProgram";
if (alias.equals("noisy")) key = "SIG3_ModeNoisyProgram";
if (alias.equals("vnoisy") || alias.equals("very noisy") || alias.equals("verynoisy")) key = "SIG3_ModeVeryNoisyProgram";
if (key != null) {
    slot = tasker.getVariable(key);
    if (slot == null || !slot.matches("[1-6]")) throw new JavaCodeException("Configure " + key + " to an actual program slot");
    input = "program " + slot;
}
if (alias.equals("sleep")) input = "sleep";
if (alias.equals("awake") || alias.equals("wake")) input = "wake";
tasker.setVariable("sig3_command", input);
return "normalized";

/* Load or atomically save independent speech preferences. */
voicePreferenceValue(name) {
    value = tasker.getVariable(name);
    return value == null || value.startsWith("%") ? "" : value;
}
voicePreferenceValid(value) { return "0".equals(value) || "1".equals(value); }
prefs = context.getSharedPreferences("heysig3-voice", 0);
mode = voicePreferenceValue("sig3_voice_pref_mode");
if ("save".equals(mode)) {
    responses = voicePreferenceValue("sig3_voice_results_choice");
    prompts = voicePreferenceValue("sig3_voice_prompts_choice");
    if (!voicePreferenceValid(responses) || !voicePreferenceValid(prompts))
        throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Invalid voice preference selection");
    if (!prefs.edit().putString("responses", responses).putString("prompts", prompts).commit())
        throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Voice preferences could not be saved");
} else if ("load".equals(mode)) {
    responses = voicePreferenceValue("SIG3_VoiceResponses");
    if (!voicePreferenceValid(responses)) responses = prefs.getString("responses", "1");
    if (!voicePreferenceValid(responses)) responses = "1";
    prompts = voicePreferenceValue("SIG3_VoicePrompts");
    if (!voicePreferenceValid(prompts)) prompts = prefs.getString("prompts", responses);
    if (!voicePreferenceValid(prompts)) prompts = responses;
} else throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Unknown voice preference operation");
tasker.setVariable("SIG3_VoiceResponses", responses);
tasker.setVariable("SIG3_VoicePrompts", prompts);
tasker.setVariable("SIG3_VoiceSettingsStatus", "Spoken results " + ("1".equals(responses) ? "on" : "off") + "; voice prompts " + ("1".equals(prompts) ? "on" : "off"));
return "voice preferences " + mode;

/* Prepare the readiness cue before opening microphone capture. */
import android.content.pm.PackageManager;
import android.app.NotificationManager;
import android.media.AudioManager;
readyValue(name) {
    value = tasker.getVariable(name);
    return value == null || value.startsWith("%") ? "" : value;
}
tasker.setVariable("sig3_ready_speech", "");
tasker.setVariable("SIG3_VoiceReady", "0");
tasker.setVariable("SIG3_VoiceCaptureAllowed", "0");
status = "";
pm = context.getSystemService("power"); km = context.getSystemService("keyguard");
if (!pm.isInteractive() || km.isKeyguardLocked()) status = "Turn on and unlock the phone to speak a command";
else if (context.checkSelfPermission("android.permission.RECORD_AUDIO") != PackageManager.PERMISSION_GRANTED) status = "Allow Tasker microphone access to speak a command";
else if (readyValue("TRUN").matches("(?s).*(?:^|,)SIG3_Worker(?:,|$).*")) status = "Wait for the current command to finish";
