} else throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Unknown voice preference operation");
tasker.setVariable("SIG3_VoiceResponses", responses);
tasker.setVariable("SIG3_VoicePrompts", prompts);
tasker.setVariable("SIG3_VoiceSettingsStatus", "Spoken results " + ("1".equals(responses) ? "on" : "off") + "; voice prompts " + ("1".equals(prompts) ? "on" : "off"));
return "voice preferences " + mode;

/* Speak only a fresh completed voice result, using actual app readback. */
voiceValue(name) {
    value = tasker.getVariable(name);
    return value == null || value.startsWith("%") ? "" : value;
}
tasker.setVariable("sig3_speech", "");
tasker.setVariable("SIG3_VoiceReply", "");
retry = "retry".equals(voiceValue("sig3_reply_kind"));
preference = voiceValue(retry ? "SIG3_VoicePrompts" : "SIG3_VoiceResponses");
if (retry && preference.length() == 0) preference = voiceValue("SIG3_VoiceResponses");
if ("0".equals(preference)) return "disabled";
running = voiceValue("TRUN");
if (running.matches("(?s).*(?:^|,)SIG3_Worker(?:,|$).*")) return "worker-busy";
if ("retry".equals(voiceValue("sig3_reply_kind"))) {
    reply = "Command not recognized. Tap Try again to speak again, or Cancel.";
} else {
    operation = voiceValue("SIG3_OperationId");
    if (operation.length() == 0 || operation.equals(voiceValue("sig3_reply_before"))) {
        reply = "Command was not accepted. Please try again when the current command finishes.";
    } else if (!"1".equals(voiceValue("SIG3_CommandOK"))) {
        error = voiceValue("SIG3_Error");
        reply = error.length() == 0 ? "Command did not complete. Check the phone screen." : "Command stopped. " + error;
        if (error.startsWith("Turn off Do Not Disturb")) reply = "Turn off Do Not Disturb.";
        if (error.startsWith("Raise phone ")) {
            end = error.indexOf(" volume");
            if (end > 12) {
                stream = error.substring(12, end);
                reply = "Raise phone " + stream + " volume" + (error.contains("(50% minimum)") ? " to halfway." : ".");
            }
        }
    } else if (!"complete".equals(voiceValue("SIG3_MoveStage"))) {
        reply = "Command result could not be verified. Check the phone screen.";
    } else {
        family = voiceValue("SIG3_Family");
        observed = voiceValue("SIG3_Observed");
        program = voiceValue("SIG3_Program");
        reply = "Command completed. Check the phone screen.";
        if ("Program".equals(family) && program.length() > 0) reply = "Program is " + program + ".";
        if ("Volume".equals(family) || "Balance".equals(family) || "Tinnitus".equals(family)) {
            if (observed.matches("-?[0-9]+")) {
                spoken = observed.startsWith("-") ? "minus " + observed.substring(1) : observed;
                reply = family + " is " + spoken + ".";
            }
        }
        if ("Battery".equals(family)) reply = "Battery checks requested. Listen for the hearing aid indications.";
        if (("Noise".equals(family) || "Setup".equals(family) || "Sleep".equals(family) || "Settings".equals(family)) && observed.length() > 0)
            reply = observed + ".";
        if (voiceValue("SIG3_SettingsAutoError").length() > 0) reply += " Settings were not saved. " + voiceValue("SIG3_SettingsAutoError");
    }
}
tasker.setVariable("SIG3_VoiceReply", reply);
tasker.setVariable("sig3_speech", reply);
return "ready";

/* Reopen recognition only after an explicit Try again choice. */
import android.app.Activity;
import android.app.AlertDialog;
import android.content.DialogInterface;
import android.os.Handler;
import android.os.Looper;
import android.view.KeyEvent;
import java.util.function.Consumer;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

choice = new AtomicReference("cancel");
activityRef = new AtomicReference();
dialogRef = new AtomicReference();
done = new CountDownLatch(1);
ui = new Handler(Looper.getMainLooper());
tasker.setVariable("sig3_retry", "cancel");
heard = tasker.getVariable("SIG3_VoiceHeard");
message = heard == null || heard.length() == 0 || heard.startsWith("%")
    ? "No command was recognized. Try speaking again?"
    : "I heard: " + heard + "\nThat command was not recognized. Try speaking again?";
try {
    tasker.doWithActivity(new Consumer() {
        accept(Object value) {
            final Activity screen = (Activity) value;
            activityRef.set(screen);
            buttons = new DialogInterface.OnClickListener() {
                onClick(DialogInterface dialog, int which) {
                    if (which == DialogInterface.BUTTON_POSITIVE) choice.set("retry");
                }
            };
            dialog = new AlertDialog.Builder(screen).setTitle("HeySig3 voice")
                .setMessage(message).setPositiveButton("Try again", buttons)
                .setNegativeButton("Cancel", buttons).create();
            dialogRef.set(dialog);
            dialog.setCancelable(true);
            dialog.setOnKeyListener(new DialogInterface.OnKeyListener() {
                onKey(DialogInterface current, int keyCode, KeyEvent event) {
                    if (keyCode != KeyEvent.KEYCODE_BACK) return false;
                    if (event.getAction() == KeyEvent.ACTION_UP) {
                        choice.set("cancel");
                        current.cancel();
                    }
                    return true;
                }
            });
            dialog.setOnDismissListener(new DialogInterface.OnDismissListener() {
                onDismiss(DialogInterface dialog) {
                    done.countDown();
                    screen.finish();
                }
            });
            dialog.show();
        }
    });
    if (done.await(60, TimeUnit.SECONDS)) tasker.setVariable("sig3_retry", choice.get());
} finally {
    ui.post(new Runnable() {
        run() {
            dialog = dialogRef.get();
            if (dialog != null && dialog.isShowing()) dialog.dismiss();
            screen = activityRef.get();
            if (screen != null && !screen.isFinishing()) screen.finish();
        }
    });
}
return tasker.getVariable("sig3_retry");

/* Preserve the media level across AutoVoice continuous mute cycles. */
import android.media.AudioManager;
wakeAudioValue(name) {
    value = tasker.getVariable(name);
    return value == null || value.startsWith("%") ? "" : value;
}
am = context.getSystemService("audio");
mode = wakeAudioValue("sig3_wake_audio_mode");
if ("capture".equals(mode)) {
    tasker.setVariable("SIG3_WakeMediaLevel", "" + am.getStreamVolume(AudioManager.STREAM_MUSIC));
    return "media captured";
}
if (!"restore".equals(mode)) throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Unknown wake audio operation");
saved = wakeAudioValue("SIG3_WakeMediaLevel");
if (!saved.matches("[0-9]+")) return "no captured media level";
level = Integer.parseInt(saved);
if (level > am.getStreamMaxVolume(AudioManager.STREAM_MUSIC))
    throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Captured media level is outside the phone range");
// Allow the stopped plugin to finish releasing its suppression before restoration.
Thread.sleep(500);
if (am.getStreamVolume(AudioManager.STREAM_MUSIC) != level)
    am.setStreamVolume(AudioManager.STREAM_MUSIC, level, 0);
if (level > 0 && am.isStreamMute(AudioManager.STREAM_MUSIC))
    am.adjustStreamVolume(AudioManager.STREAM_MUSIC, AudioManager.ADJUST_UNMUTE, 0);
if (am.getStreamVolume(AudioManager.STREAM_MUSIC) != level)
    throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Phone media volume did not restore");
return "media restored";

