/* Accept only the wake phrase while our listener is enabled and idle. */
wakeValue(name) {
    value = tasker.getVariable(name);
    return value == null || value.startsWith("%") ? "" : value;
}
tasker.setVariable("sig3_wake_accepted", "0");
if (!"1".equals(wakeValue("SIG3_WakeEnabled")) || "1".equals(wakeValue("SIG3_VoiceBusy"))) return "disabled-or-busy";
if (wakeValue("TRUN").matches("(?s).*(?:^|,)SIG3_Worker(?:,|$).*")) return "worker-busy";
heard = wakeValue("par1");
if (heard.length() == 0) heard = wakeValue("avcommnofilter");
if (heard.length() == 0) heard = wakeValue("avcomm");
if (!heard.trim().matches("(?i)^hey\\s+(?:sig|cig)[.!?]?$")) return "not-wake-phrase";
tasker.setVariable("sig3_wake_accepted", "1");
return "wake-accepted";

/* Load or atomically save independent speech preferences. */
voicePreferenceValue(name) {
    value = tasker.getVariable(name);
    return value == null || value.startsWith("%") ? "" : value;
}
voicePreferenceValid(value) { return "0".equals(value) || "1".equals(value); }
prefs = context.getSharedPreferences("heysig3-voice", 0);
mode = voicePreferenceValue("sig3_voice_pref_mode");
if ("save".equals(mode)) {
    responses = voicePreferenceValue("sig3_voice_results_choice");
    prompts = voicePreferenceValue("sig3_voice_prompts_choice");
    if (!voicePreferenceValid(responses) || !voicePreferenceValid(prompts))
        throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Invalid voice preference selection");
    if (!prefs.edit().putString("responses", responses).putString("prompts", prompts).commit())
        throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Voice preferences could not be saved");
} else if ("load".equals(mode)) {
    responses = voicePreferenceValue("SIG3_VoiceResponses");
    if (!voicePreferenceValid(responses)) responses = prefs.getString("responses", "1");
    if (!voicePreferenceValid(responses)) responses = "1";
    prompts = voicePreferenceValue("SIG3_VoicePrompts");
    if (!voicePreferenceValid(prompts)) prompts = prefs.getString("prompts", responses);
    if (!voicePreferenceValid(prompts)) prompts = responses;
} else throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Unknown voice preference operation");
tasker.setVariable("SIG3_VoiceResponses", responses);
tasker.setVariable("SIG3_VoicePrompts", prompts);
tasker.setVariable("SIG3_VoiceSettingsStatus", "Spoken results " + ("1".equals(responses) ? "on" : "off") + "; voice prompts " + ("1".equals(prompts) ? "on" : "off"));
return "voice preferences " + mode;

/* Show separate visible on/off controls; Cancel leaves preferences unchanged. */
import android.app.Activity;
import android.app.AlertDialog;
import android.content.DialogInterface;
import android.os.Handler;
import android.os.Looper;
import java.util.function.Consumer;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

selected = new boolean[] {"1".equals(tasker.getVariable("SIG3_VoiceResponses")), "1".equals(tasker.getVariable("SIG3_VoicePrompts"))};
decision = new AtomicReference("cancel"); activityRef = new AtomicReference(); dialogRef = new AtomicReference(); done = new CountDownLatch(1);
ui = new Handler(Looper.getMainLooper());
tasker.setVariable("sig3_voice_settings_decision", "cancel");
try {
    tasker.doWithActivity(new Consumer() {
        accept(Object value) {
            final Activity screen = (Activity) value; activityRef.set(screen);
            dialog = new AlertDialog.Builder(screen).setTitle("HeySig3 voice settings")
                .setMultiChoiceItems(new String[] {"Spoken results", "Voice prompts"}, selected, new DialogInterface.OnMultiChoiceClickListener() {
                    onClick(DialogInterface dialog, int which, boolean checked) { selected[which] = checked; }
                }).setPositiveButton("Save", new DialogInterface.OnClickListener() {
                    onClick(DialogInterface dialog, int which) { decision.set("save"); }
                }).setNegativeButton("Cancel", null).create();
            dialogRef.set(dialog); dialog.setCancelable(true);
            dialog.setOnDismissListener(new DialogInterface.OnDismissListener() {
                onDismiss(DialogInterface dialog) { done.countDown(); screen.finish(); }
            });
            dialog.show();
        }
    });
    if (done.await(60, TimeUnit.SECONDS) && "save".equals(decision.get())) {
        tasker.setVariable("sig3_voice_results_choice", selected[0] ? "1" : "0");
        tasker.setVariable("sig3_voice_prompts_choice", selected[1] ? "1" : "0");
        tasker.setVariable("sig3_voice_settings_decision", "save");
    }
} finally {
    ui.post(new Runnable() {
        run() {
            dialog = dialogRef.get(); if (dialog != null && dialog.isShowing()) dialog.dismiss();
            screen = activityRef.get(); if (screen != null && !screen.isFinishing()) screen.finish();
        }
    });
}
return tasker.getVariable("sig3_voice_settings_decision");

